 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import FollowButton from '../components/follow/FollowButton'

export default function Community() {
    const { user, profile } = useAuth()
    const [predictions, setPredictions] = useState([])
    const [loading, setLoading] = useState(true)
    const [tab, setTab] = useState('following') // 'following' | 'all' | 'top'

    useEffect(() => {
        loadPredictions()
    }, [tab])

    const loadPredictions = async () => {
        setLoading(true)
        try {
            let query = supabase
                .from('shared_predictions')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url, points),
                    matches (id, home_team, away_team, league, kickoff)
                `)
                .order('shared_at', { ascending: false })

            // If 'following' tab, only show predictions from followed users
            if (tab === 'following' && user) {
                // Get users this user follows
                const { data: following } = await supabase
                    .from('followers')
                    .select('following_id')
                    .eq('follower_id', user.id)

                const followingIds = following?.map(f => f.following_id) || []
                
                // If not following anyone, show message
                if (followingIds.length === 0) {
                    setPredictions([])
                    setLoading(false)
                    return
                }

                query = query.in('user_id', followingIds)
            }

            // If 'top' tab, get most points
            if (tab === 'top') {
                query = query.order('points_earned', { ascending: false })
            }

            const { data, error } = await query

            if (error) throw error
            setPredictions(data || [])
        } catch (error) {
            console.error('Error loading predictions:', error)
            setPredictions([])
        } finally {
            setLoading(false)
        }
    }

    const renderPrediction = (pred) => {
        const isOwn = user?.id === pred.user_id
        const predData = pred.prediction_data || {}
        
        let resultEmoji = '🤝'
        if (predData.result === 'Home Win') resultEmoji = '🏠'
        else if (predData.result === 'Away Win') resultEmoji = '✈️'

        return (
            <div key={pred.id} className="bg-white rounded-xl shadow-md p-4 hover:shadow-lg transition">
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                            {pred.profiles?.username?.[0]?.toUpperCase() || 'U'}
                        </div>
                        <div>
                            <div className="font-semibold flex items-center gap-2">
                                {pred.profiles?.full_name || pred.profiles?.username || 'Unknown'}
                                {pred.profiles?.points !== undefined && (
                                    <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded-full">
                                        🏆 {pred.profiles.points} pts
                                    </span>
                                )}
                            </div>
                            <div className="text-sm text-gray-500">
                                {pred.matches?.home_team || 'Unknown'} vs {pred.matches?.away_team || 'Unknown'}
                            </div>
                        </div>
                    </div>
                    {!isOwn && (
                        <FollowButton 
                            userId={pred.user_id} 
                            username={pred.profiles?.username}
                        />
                    )}
                </div>

                <div className="mt-3 bg-gray-50 rounded-lg p-3">
                    <div className="flex items-center justify-between flex-wrap gap-2">
                        <div className="flex items-center gap-2">
                            <span className="text-lg">{resultEmoji}</span>
                            <span className="font-bold text-gray-800">{predData.result || 'Draw'}</span>
                        </div>
                        <div className="flex items-center gap-4 text-sm text-gray-500">
                            <span>🟨 {predData.yellowCards || 0}</span>
                            <span>🟥 {predData.redCards || 0}</span>
                            <span>🏁 {predData.corners || 0}</span>
                            <span>🚩 {predData.offsides || 0}</span>
                        </div>
                        <div className="text-sm font-semibold text-green-600">
                            +{pred.points_earned || 0} pts
                        </div>
                    </div>
                </div>

                <div className="mt-2 flex justify-between text-xs text-gray-400">
                    <span>📅 {new Date(pred.shared_at).toLocaleDateString()}</span>
                    {pred.is_correct && <span className="text-green-600">✅ Correct</span>}
                    {pred.is_correct === false && <span className="text-red-500">❌ Incorrect</span>}
                </div>
            </div>
        )
    }

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">👥 Community</h1>
                    <p className="text-gray-500">See predictions from people you follow</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={() => setTab('following')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            tab === 'following' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        Following
                    </button>
                    <button
                        onClick={() => setTab('all')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            tab === 'all' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        All
                    </button>
                    <button
                        onClick={() => setTab('top')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            tab === 'top' 
                                ? 'bg-yellow-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        🏆 Top
                    </button>
                </div>
            </div>

            {!user ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">🔒</div>
                    <p className="text-gray-500">Please sign in to see community predictions</p>
                </div>
            ) : loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading predictions...</div>
                </div>
            ) : predictions.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    {tab === 'following' ? (
                        <>
                            <div className="text-4xl mb-4">👀</div>
                            <p className="text-gray-500">You're not following anyone yet</p>
                            <p className="text-sm text-gray-400">Follow other users to see their predictions here</p>
                            <button 
                                onClick={() => setTab('all')}
                                className="mt-4 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                            >
                                See All Predictions
                            </button>
                        </>
                    ) : (
                        <>
                            <div className="text-4xl mb-4">📊</div>
                            <p className="text-gray-500">No predictions shared yet</p>
                            <p className="text-sm text-gray-400">Be the first to share your prediction!</p>
                        </>
                    )}
                </div>
            ) : (
                <div className="space-y-4">
                    {predictions.map(renderPrediction)}
                </div>
            )}
        </div>
    )
}
